// Shinkansen N700S geometry — auto-generated from model.dae
// 85900 triangles, 257700 vertices (non-indexed, interleaved pos+nrm float32)
const SHINKANSEN_VERT_COUNT = 257700;
const SHINKANSEN_B64 = '';
function getShinkansenGeo(){
  const raw = atob(SHINKANSEN_B64);
  const buf = new ArrayBuffer(raw.length);
  const u8  = new Uint8Array(buf);
  for (let i = 0; i < raw.length; i++) u8[i] = raw.charCodeAt(i);
  return new Float32Array(buf);
}
